insert into public.client_notes (id, profile_id, coach_id, body, noted_on, pinned, created_at) values
  ('5eed0600-001b-4000-8000-000000000001', '5eed0600-0002-4000-8000-000000000001', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Wants to be braver in board meetings. Prefers early calls before the school run.', polish_seed.d('2026-10-16'), true, polish_seed.ts('2026-10-16 17:00')),
  ('5eed0600-001b-4000-8000-000000000002', '5eed0600-0002-4000-8000-000000000003', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Restructure announced in January: keep space for it.', polish_seed.d('2026-11-05'), true, polish_seed.ts('2026-11-05 17:00')),
  ('5eed0600-001b-4000-8000-000000000003', '5eed0600-0002-4000-8000-000000000005', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Finance team of 40. Most of her week is in back-to-back meetings.', polish_seed.d('2026-09-26'), false, polish_seed.ts('2026-09-26 17:00')),
  ('5eed0600-001b-4000-8000-000000000004', '5eed0600-0002-4000-8000-000000000006', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Prefers to meet in person at the Leeds office.', polish_seed.d('2026-10-01'), true, polish_seed.ts('2026-10-01 17:00')),
  ('5eed0600-001b-4000-8000-000000000005', '5eed0600-0002-4000-8000-00000000000c', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Renewal conversation due before Christmas. He has asked about a quarterly retainer.', polish_seed.d('2026-11-15'), true, polish_seed.ts('2026-11-15 17:00')),
  ('5eed0600-001b-4000-8000-000000000006', '5eed0600-0002-4000-8000-00000000000d', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Last two sessions: focus on handing over the product roadmap.', polish_seed.d('2026-11-11'), false, polish_seed.ts('2026-11-11 17:00')),
  ('5eed0600-001b-4000-8000-000000000007', '5eed0600-0002-4000-8000-000000000015', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Paused for parental leave. Back in the new year.', polish_seed.d('2026-09-01'), true, polish_seed.ts('2026-09-01 17:00')),
  ('5eed0600-001b-4000-8000-000000000008', '5eed0600-0002-4000-8000-000000000016', 'c03c9b0e-1bc2-85f3-31d7-9bf5f15f8829', 'Paused while he moves house. Check in mid-December.', polish_seed.d('2026-10-15'), true, polish_seed.ts('2026-10-15 17:00'));
